//! The Leyline-shaped service: the extension points a real Crucible service
//! uses, wired the way `docs/framework.md` lays a service out.
//!
//! ```text
//! src/
//!   operations/    one file per operation
//!   middlewares/   RequestTag (async Middleware), TenantGate (operation-aware)
//!   interceptors/  Audit
//!   access/        ScopeBindings (the BindingSource the RoleAuthorizer reads)
//! ```

// The model's types, errors and operation traits, generated by build.rs.
crucible_server_runtime_rust::include_service!();
mod access;
mod interceptors;
mod middlewares;
mod operations;
mod service;

pub use access::ScopeBindings;
pub use interceptors::Audit;
pub use middlewares::{RequestTag, TenantGate};
pub use operations::Leyline;
pub use service::service;
